ublish_year":1623,"native_identity_key":"nlscale:fixture040:323"}},{"ref":"e1","relation":"editions","key":{"open_library_edition_id":"OL34490134M"},"before":null,"after":{"work_id":987139004,"title":"Macbeth","language":"dut","open_library_edition_id":"OL34490134M","isbn_13":"9789064032295","isbn_10":null,"publisher":"International Theatre & Film Books","id":987239021,"publish_date":null,"cover_id":null}},{"ref":"d1","relation":"catalog_work_descriptions","key":{"work_id":987139004,"language":"nl"},"before":null,"after":{"work_id":987139004,"language":"nl","bound_author_id":987311001,"text":"Macbeth is een gerespecteerde legeraanvoerder wanneer een voorspelling zijn verlangen naar macht versterkt. Aangemoedigd door zijn vrouw besluit hij een grens over te gaan om de kroon te bereiken. De verkregen positie brengt hem echter geen zekerheid. Angst voor verlies en wantrouwen leiden tot nieuwe gewelddadige keuzes. Het toneelstuk volgt hoe ambitie steeds meer van zijn denken en handelen gaat bepalen, totdat de macht die hij zocht zijn bestaan volledig beheerst.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.folger.edu/explore/shakespeares-works/macbeth/an-introduction-to-this-text/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p05864119X"],"reference":"work:323","checked_at":"2026-11-03T08:16:03.676Z","note":"Complete Dutch theatre text Macbeth9789064032295, not a prose retelling or English edition. Folger confirms first PRINT publication1623, distinguish composition circa1606; current1508 is impossible. Worktype/taste features unchanged.","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://www.folger.edu/explore/shakespeares-works/macbeth/an-introduction-to-this-text/","https://openlibrary.org/works/OL258902W","https://data.bibliotheken.nl/id/