that no cover exists at the provider or elsewhere."}],"review_status":"approved","reviewed_at":"2026-11-03T08:16:03.676Z","review_batch":"nl-scale-20261102-040"}},{"ref":"y14","relation":"works","key":{"id":987139012},"before":{"id":987139012,"title":"Tell No One","cover_id":null,"author_id":987304003,"work_type":null,"source_type":"open_library","open_library_id":"OL79319W","first_publish_year":2000,"native_identity_key":"nlscale:fixture040:585"},"after":{"id":987139012,"title":"Tell No One","cover_id":null,"author_id":987304003,"work_type":null,"source_type":"open_library","open_library_id":"OL79319W","first_publish_year":2001,"native_identity_key":"nlscale:fixture040:585"}},{"ref":"e14","relation":"editions","key":{"open_library_edition_id":"OL45867977M"},"before":null,"after":{"work_id":987139012,"title":"Niemand vertellen","language":"dut","open_library_edition_id":"OL45867977M","isbn_13":"9789022530450","isbn_10":null,"publisher":"De Boekerij","id":987239034,"publish_date":null,"cover_id":null}},{"ref":"d14","relation":"catalog_work_descriptions","key":{"work_id":987139012,"language":"nl"},"before":null,"after":{"work_id":987139012,"language":"nl","bound_author_id":987304003,"text":"Acht jaar na de dood van zijn vrouw Elizabeth ontvangt arts David Beck een anoniem bericht met een verwijzing die alleen zij samen kenden. Een beeld op internet lijkt vervolgens te tonen dat Elizabeth nog leeft. Zijn poging te begrijpen wat hij ziet, opent het oude onderzoek opnieuw. Tegelijk krijgt hij zelf te maken met verdenkingen en gevaar. Beck moet bepalen of het bericht hoop biedt of onderdeel is van iets dat de herinnering aan hun laatste gezamenlijke dag bewust manipuleert.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL79319W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p237530015"],"reference":"work:585","checked_at":"2026-