auwelijks kan uiten. Sylvia krijgt steeds sterker het gevoel dat haar patiënte iets belangrijks probeert duidelijk te maken. Wat een overzichtelijke zorgtaak leek, roept daardoor steeds meer vragen op over het huishouden waarin zij terechtgekomen is.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL26121595W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p444714715"],"reference":"work:589","checked_at":"2026-11-03T08:16:03.676Z","note":"FreidaMcFadden TheWifeUpstairs2020 Victoria/Sylvia, exactDutchDeVrouwOpZolder9789032521479. Distinct fromRachelHawkins identically titled2021novel; no inferred author merge.","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL26121595W","https://data.bibliotheken.nl/id/nbt/p444714715"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL61057863M","isbn13":"9789032521479","checkedAt":"2026-11-03T08:16:03.677Z","note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15158672,"status":"bulk_archive_unavailable","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-03T08:16:03.676Z","review_batch":"nl-scale-20261102-040"}},{"ref":"m18","relation":"catalog_edition_metadata","key":{"edition_id":"@e18"},"before":null,"after":{"edition_id":"@e18","work_id":9871